/**
 * issue #75: stock `HTTP In -> ... -> HTTP Response` transport-edge bridge.
 *
 * Reuses issue #58's proven durability contract (`./httpIngress.js`): only
 * plain, serializable request/response data ever crosses into Temporal
 * Workflow/Activity input/output/history. Live Express `req`/`res` objects
 * (sockets, streams, functions, circular/process-bound state) never do.
 *
 * This module is intentionally small and generic - it has no knowledge of
 * Temporal, Workflows, or Activities:
 *
 *   - `isStockHttpIngress(node)` / `isStockHttpResponse(node)` - classify a
 *     live Node-RED node by its stock type ("http in" / "http response").
 *   - `snapshotRequestMessage(msg)` - turns a stock HTTP In message (which
 *     carries a live Express `req` and a `res` wrapper) into a plain,
 *     Temporal-serializable message. `msg.req`/`msg.res` themselves are
 *     never copied through; only the documented plain subset of `req` is.
 *   - `createResponseRecorder()` - a tiny Activity-local stand-in for the
 *     real Express response, implementing only the methods the stock HTTP
 *     Response node (`@node-red/nodes/core/network/21-httpin.js`) actually
 *     calls: `set`, `get`, `status`, `cookie`, `clearCookie`, `send`,
 *     `jsonp`. The real, unmodified stock node executes against this
 *     recorder and never learns the difference.
 *   - `applyResponseDescriptor(res, descriptor)` - maps the recorder's
 *     plain descriptor onto the ORIGINAL live Express response, at the
 *     process-local transport edge only.
 *
 * See the stock node's own source for the exact contract this bridges:
 *   - HTTP In's `callback` sends `{_msgid, req, res: createResponseWrapper(...), payload}`
 *     with the RAW live Express `req` (not wrapped) and only `res` wrapped
 *     (`{_res: res, ...deprecation-warning-wrapped methods}`).
 *   - HTTP Response's `input` handler only ever calls, on `msg.res._res`:
 *     `set(headers)`, `get('content-length')`, `clearCookie(name[,opts])`,
 *     `cookie(name,value[,opts])`, `status(code).jsonp(payload)` or
 *     `status(code).send(payload)`.
 */

"use strict";

const { sanitizeHeaders, isValidHttpStatus, STRIPPED_RESPONSE_HEADERS } = require("./httpIngress");

/**
 * @param {object} [node] - a live Node-RED node instance (or node metadata
 *     with a `.type`)
 * @returns {boolean} true iff `node` is a stock "http in" node
 */
function isStockHttpIngress(node) {
    return !!(node && node.type === "http in");
}

/**
 * @param {object} [node]
 * @returns {boolean} true iff `node` is a stock "http response" node
 */
function isStockHttpResponse(node) {
    return !!(node && node.type === "http response");
}

/**
 * Extracts only the documented, plain-serializable subset of a live Express
 * `req` - see the module docblock. Never includes `req.socket`, streaming
 * methods, or any other function/circular-reference-bearing property.
 *
 * @param {object} req - the live Express request (or already-plain snapshot)
 * @returns {object}
 */
function snapshotRequest(req) {
    if (!req) {
        return undefined;
    }
    return {
        method: req.method,
        headers: sanitizeHeaders(req.headers || {}),
        params: req.params,
        query: req.query,
        body: req.body,
        originalUrl: req.originalUrl,
        path: req.path,
        hostname: req.hostname,
        ip: req.ip,
        protocol: req.protocol,
        secure: !!req.secure
    };
}

/**
 * Turns one stock HTTP In message into a plain, Temporal-serializable
 * message: every ordinary field is preserved as-is, `req` is replaced by
 * `snapshotRequest(msg.req)`, and `res` (the live Express response wrapper)
 * is dropped entirely - the real response is only ever reachable from the
 * process-local ingress handler's own closure (see `worker.js`), never
 * through Workflow/Activity input.
 *
 * Does not mutate `msg` - the original live message (still carrying its
 * real `req`/`res`) is left untouched so the process-local ingress handler
 * can keep using it after this snapshot is taken.
 *
 * @param {object} msg
 * @returns {object} a new, plain object safe for Temporal payload conversion
 */
function snapshotRequestMessage(msg) {
    const snapshot = {};
    Object.keys(msg || {}).forEach(function(key) {
        if (key === "req" || key === "res") {
            return;
        }
        snapshot[key] = msg[key];
    });
    if (msg && msg.req) {
        snapshot.req = snapshotRequest(msg.req);
    }
    return snapshot;
}

/**
 * Creates a small Activity-local recorder implementing only the Express
 * response surface the real stock HTTP Response node calls on
 * `msg.res._res`. Chainable methods (`status`, `set`, `cookie`,
 * `clearCookie`) return the SAME recorder object, matching Express's own
 * chaining contract (`res.status(x).send(y)`).
 *
 * Cookie serialization is a small, best-effort subset (name/value plus
 * `path`, `expires`, `maxAge`, `httpOnly`, `secure`, `sameSite`) - not a
 * full Express/`cookie` package reimplementation, since only the plain
 * descriptor needs to survive the Activity boundary; the actual bytes
 * written to the wire are still produced by Node's own `res.writeHead`
 * at the process-local transport edge (`applyResponseDescriptor`).
 *
 * @returns {{res:object, toDescriptor:function(): object}}
 */
function createResponseRecorder() {
    const state = {
        statusCode: undefined,
        headers: {},
        cookies: [],
        body: undefined,
        bodySet: false
    };

    const recorder = {
        status(code) {
            state.statusCode = code;
            return recorder;
        },
        set(field, value) {
            if (field && typeof field === "object") {
                Object.keys(field).forEach(function(name) {
                    state.headers[String(name).toLowerCase()] = field[name];
                });
            } else if (field !== undefined) {
                state.headers[String(field).toLowerCase()] = value;
            }
            return recorder;
        },
        get(field) {
            return state.headers[String(field).toLowerCase()];
        },
        cookie(name, value, options) {
            state.cookies.push({ name: name, value: value, options: options || {}, cleared: false });
            return recorder;
        },
        clearCookie(name, options) {
            state.cookies.push({ name: name, value: "", options: options || {}, cleared: true });
            return recorder;
        },
        send(body) {
            state.body = body;
            state.bodySet = true;
            return recorder;
        },
        jsonp(body) {
            state.body = body;
            state.bodySet = true;
            if (state.headers["content-type"] === undefined) {
                state.headers["content-type"] = "application/json";
            }
            return recorder;
        }
    };

    return {
        res: recorder,
        /**
         * @returns {{statusCode:number, headers:object, cookies:Array, body:*}}
         */
        toDescriptor() {
            return {
                statusCode: isValidHttpStatus(state.statusCode) ? state.statusCode : 200,
                headers: Object.assign({}, state.headers),
                cookies: state.cookies.slice(),
                body: state.body
            };
        }
    };
}

/**
 * Serializes one recorded cookie into a `Set-Cookie` header value - a small
 * subset of the real `cookie` package's `serialize()`, sufficient for the
 * common attributes the stock HTTP Response node's `msg.cookies` contract
 * exposes (see `21-httpin.js`'s `HTTPOut`).
 *
 * @param {{name:string, value:string, options:object, cleared:boolean}} cookie
 * @returns {string}
 */
function serializeCookie(cookie) {
    const options = cookie.options || {};
    const parts = [`${cookie.name}=${cookie.cleared ? "" : encodeURIComponent(cookie.value === undefined ? "" : cookie.value)}`];
    if (cookie.cleared) {
        parts.push("Expires=Thu, 01 Jan 1970 00:00:00 GMT");
    } else if (options.maxAge !== undefined) {
        parts.push(`Max-Age=${Math.floor(options.maxAge / 1000)}`);
    } else if (options.expires) {
        const expires = options.expires instanceof Date ? options.expires : new Date(options.expires);
        parts.push(`Expires=${expires.toUTCString()}`);
    }
    parts.push(`Path=${options.path || "/"}`);
    if (options.domain) {
        parts.push(`Domain=${options.domain}`);
    }
    if (options.httpOnly) {
        parts.push("HttpOnly");
    }
    if (options.secure) {
        parts.push("Secure");
    }
    if (options.sameSite) {
        const sameSite = typeof options.sameSite === "string" ? options.sameSite : "Strict";
        parts.push(`SameSite=${sameSite.charAt(0).toUpperCase()}${sameSite.slice(1)}`);
    }
    return parts.join("; ");
}

/**
 * Maps a recorder descriptor onto the ORIGINAL live Express response - the
 * one and only place this module ever touches a real socket. Never writes
 * if the response already ended/has headers sent (matches issue #58's
 * "no write after client disconnect/response already ended" contract).
 *
 * @param {import("http").ServerResponse} res
 * @param {{statusCode:number, headers:object, cookies:Array, body:*}} [descriptor]
 */
function applyResponseDescriptor(res, descriptor) {
    if (!res || typeof res.writeHead !== "function") {
        return;
    }
    if (res.headersSent || res.writableEnded) {
        return;
    }
    descriptor = descriptor || {};
    const statusCode = isValidHttpStatus(descriptor.statusCode) ? descriptor.statusCode : 200;

    const headers = {};
    Object.keys(descriptor.headers || {}).forEach(function(name) {
        if (STRIPPED_RESPONSE_HEADERS.indexOf(name.toLowerCase()) !== -1) {
            return;
        }
        const value = descriptor.headers[name];
        if (value === null || value === undefined) {
            return;
        }
        headers[name] = value;
    });

    if (Array.isArray(descriptor.cookies) && descriptor.cookies.length) {
        headers["Set-Cookie"] = descriptor.cookies.map(serializeCookie);
    }

    const body = descriptor.body;
    let payload;
    if (body === undefined || body === null) {
        payload = Buffer.alloc(0);
    } else if (Buffer.isBuffer(body) || body instanceof Uint8Array) {
        payload = Buffer.from(body);
    } else if (typeof body === "string") {
        payload = Buffer.from(body, "utf8");
    } else {
        payload = Buffer.from(JSON.stringify(body), "utf8");
    }

    res.writeHead(statusCode, headers);
    res.end(payload);
}

module.exports = {
    isStockHttpIngress,
    isStockHttpResponse,
    snapshotRequest,
    snapshotRequestMessage,
    createResponseRecorder,
    applyResponseDescriptor,
    serializeCookie
};
